claim_compilation_result.query:
(
    df.filter(
        prompt("The customer support {dialog} contains a customer complaint")
    )
    .map(
        prompt(
            "Identify whether the support agent apologizes in the customer support {dialog}",
            bool
        ).alias("agent_apologizes")
    )
    .aggregate(
        [bool_and(col("agent_apologizes")).alias("all_apologize")],
        group_by=[col("company_id")]
    )
    .aggregate(
        [count_if(col("all_apologize")).alias("num_companies_all_apologize")]
    )
    .check(col("num_companies_all_apologize").eq(2))
)
